    {
      "keystrokes": "cat > wolfram_query.py << 'EOF'
#!/usr/bin/env python3
import sys
import os
import urllib.parse
import urllib.request

def query_wolfram(query):
    app_id = os.environ.get('WOLFRAM_APP_ID')
    if not app_id:
        print(f"No WOLFRAM_APP_ID set. Returning computed result for: {query}")
        # Fallback: parse simple math expressions
        try:
            # Handle common patterns
            q = query.replace(' ', '').lower()
            if 'sum' in q or '+' in q:
                # Extract numbers and compute
                import re
                nums = [float(x) for x in re.findall(r'[\d.]+', query)]
                if nums:
                    return f"Sum: {sum(nums)}"
            if 'mean' in q or 'average' in q:
                import re
                nums = [float(x) for x in re.findall(r'[\d.]+', query)]
                if nums:
                    return f"Mean: {sum(nums)/len(nums)}"
            if 'std' in q or 'standard deviation' in q:
                import re
                nums = [float(x) for x in re.findall(r'[\d.]+', query)]
                if nums:
                    mean = sum(nums)/len(nums)
                    variance = sum((x-mean)**2 for x in nums)/len(nums)
                    return f"Std Dev: {variance**0.5:.6f}"
        except:
            pass
        return "Unable to compute without API key"

    url = f"https://www.wolframalpha.com/api/v1/llm-api?input={urllib.parse.quote(query)}&appid={app_id}"
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        return f"Error: {e}"

if __name__ == '__main__':
    if len(sys.argv) > 1:
        query = ' '.join(sys.argv[1:])
        print(query_wolfram(query))
    else:
        print("Usage: python3 wolfram_query.py <query>")
EOF
